package swagger

import (
	"github.com/gin-gonic/gin"
	swaggerFiles "github.com/swaggo/files"
	ginSwagger "github.com/swaggo/gin-swagger"

	// Generated by `swag init` (see Makefile).
	_ "gin-quickstart/docs"
)

// @title						SIMRS API
// @version						1.0
// @description					API documentation for SIMRS.
// @host						localhost:8080
// @BasePath					/
// @schemes						http https
// @securityDefinitions.apikey	BearerAuth
// @in							header
// @name						Authorization
// @description					Enter "Bearer {token}" (the word Bearer, a space, then the access_token from /auth/login).

// Register mounts the Swagger UI at /swagger/index.html.
func Register(router *gin.Engine) {
	router.GET("/swagger/*any", ginSwagger.WrapHandler(swaggerFiles.Handler))
}
